import{_ as a,o as e,c as o,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Planificación Académica: Proyecto Sociotecnológico II (Trimestre IV)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/Planificacion_Trimestre_II-IV.md","filePath":"materias/Proyecto_Sociotecnologico_II/Planificacion_Trimestre_II-IV.md"}'),r={name:"materias/Proyecto_Sociotecnologico_II/Planificacion_Trimestre_II-IV.md"};function c(t,i,d,l,s,u){return e(),o("div",null,[...i[0]||(i[0]=[n('<h1 id="planificacion-academica-proyecto-sociotecnologico-ii-trimestre-iv" tabindex="-1">Planificación Académica: Proyecto Sociotecnológico II (Trimestre IV) <a class="header-anchor" href="#planificacion-academica-proyecto-sociotecnologico-ii-trimestre-iv" aria-label="Permalink to &quot;Planificación Académica: Proyecto Sociotecnológico II (Trimestre IV)&quot;">​</a></h1><p>Este trimestre marca el inicio del Trayecto II del PNFI. Los estudiantes avanzan desde el soporte técnico inicial (Trayecto I) hacia el desarrollo de soluciones de software y hardware orientadas a resolver necesidades de gestión de información en comunidades y organizaciones públicas o sociales.</p><hr><h2 id="📅-trimestre-iv-abordaje-diagnostico-participativo-y-formulacion-del-proyecto-unidades-1-2-y-3" tabindex="-1">📅 Trimestre IV: Abordaje, Diagnóstico Participativo y Formulación del Proyecto (Unidades 1, 2 y 3) <a class="header-anchor" href="#📅-trimestre-iv-abordaje-diagnostico-participativo-y-formulacion-del-proyecto-unidades-1-2-y-3" aria-label="Permalink to &quot;📅 Trimestre IV: Abordaje, Diagnóstico Participativo y Formulación del Proyecto (Unidades 1, 2 y 3)&quot;">​</a></h2><h3 id="📝-evaluacion-1-abordaje-comunitario-y-diagnostico-participativo-unidad-1" tabindex="-1">📝 Evaluación 1: Abordaje Comunitario y Diagnóstico Participativo (Unidad 1) <a class="header-anchor" href="#📝-evaluacion-1-abordaje-comunitario-y-diagnostico-participativo-unidad-1" aria-label="Permalink to &quot;📝 Evaluación 1: Abordaje Comunitario y Diagnóstico Participativo (Unidad 1)&quot;">​</a></h3><p><strong>Objetivo:</strong> Identificar la situación problemática en la comunidad u organización que requiera una solución informática de software o hardware acorde al alcance del PST II.</p><ul><li>Orientaciones generales del PST II: alcance, competencias esperadas y rol del desarrollador comunitario.</li><li>El Diagnóstico Participativo: técnicas de inserción, análisis de involucrados y detección de necesidades de información.</li><li>Elaboración y ejecución del Plan Diagnóstico.</li><li><strong>Actividad:</strong> <strong>Informe de Abordaje Comunitario y Socialización de Diagnóstico.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-ingenieria-de-requerimientos-y-levantamiento-de-informacion-unidad-1" tabindex="-1">📝 Evaluación 2: Ingeniería de Requerimientos y Levantamiento de Información (Unidad 1) <a class="header-anchor" href="#📝-evaluacion-2-ingenieria-de-requerimientos-y-levantamiento-de-informacion-unidad-1" aria-label="Permalink to &quot;📝 Evaluación 2: Ingeniería de Requerimientos y Levantamiento de Información (Unidad 1)&quot;">​</a></h3><p><strong>Objetivo:</strong> Aplicar técnicas de recolección de información para especificar los requerimientos del sistema a desarrollar.</p><ul><li>Técnicas e instrumentos de recolección de datos (entrevistas, encuestas, observación directa, revisión documental).</li><li>Identificación de Requerimientos Funcionales (RF) y Requerimientos No Funcionales (RNF).</li><li>Matriz de Trazabilidad y validación de requerimientos con los actores comunitarios.</li><li><strong>Actividad:</strong> <strong>Documento de Especificación de Requerimientos de Software (ERS) / Taller Práctico.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-planteamiento-del-problema-bajo-el-enfoque-de-marco-logico-unidad-2" tabindex="-1">📝 Evaluación 3: Planteamiento del Problema bajo el Enfoque de Marco Lógico (Unidad 2) <a class="header-anchor" href="#📝-evaluacion-3-planteamiento-del-problema-bajo-el-enfoque-de-marco-logico-unidad-2" aria-label="Permalink to &quot;📝 Evaluación 3: Planteamiento del Problema bajo el Enfoque de Marco Lógico (Unidad 2)&quot;">​</a></h3><p><strong>Objetivo:</strong> Estructurar de manera rigurosa las causas, efectos y objetivos del proyecto sociotecnológico.</p><ul><li>Definición y delimitación del problema central.</li><li>Construcción del Árbol del Problema (causas directas/indirectas, efectos directos/indirectos).</li><li>Transformación al Árbol de Objetivos (medios y fines).</li><li>Justificación, beneficiarios directos/indirectos y alcance sociotecnológico.</li><li><strong>Actividad:</strong> <strong>1er Informe de Avance (Capítulo I y Árboles EML) / Defensa.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-estudio-de-factibilidad-y-planificacion-del-proyecto-unidad-3" tabindex="-1">📝 Evaluación 4: Estudio de Factibilidad y Planificación del Proyecto (Unidad 3) <a class="header-anchor" href="#📝-evaluacion-4-estudio-de-factibilidad-y-planificacion-del-proyecto-unidad-3" aria-label="Permalink to &quot;📝 Evaluación 4: Estudio de Factibilidad y Planificación del Proyecto (Unidad 3)&quot;">​</a></h3><p><strong>Objetivo:</strong> Evaluar la viabilidad integral de la propuesta informática y estructurar el cronograma de trabajo.</p><ul><li>Estudio de Factibilidad Multidimensional: Técnica (hardware, software, conectividad), Operativa (adopción del usuario), Económica y Legal (Soberanía Tecnológica, Ley de Infogobierno y Software Libre).</li><li>Elaboración del Cronograma de Actividades (Diagrama de Gantt, hitos y distribución de tareas).</li><li>Matriz de Marco Lógico preliminar.</li><li><strong>Actividad:</strong> <strong>Informe de Factibilidad y Plan de Proyecto / Examen Escrito.</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Al culminar el Trimestre IV, los equipos de proyecto contarán con su comunidad asignada, el problema plenamente diagnosticado bajo EML, la factibilidad demostrada y los requerimientos funcionales documentados, listos para seleccionar la metodología de desarrollo y comenzar el modelado en el siguiente trimestre.</p>',19)])])}const g=a(r,[["render",c]]);export{p as __pageData,g as default};
